export const ProviderIcons = {
  amplitude: AmplitudeIcon,
  aws_athena_connector: ConnectorIcon,
  bigquery: BigQueryIcon,
  cloudflare_workers_observability: CloudflareIcon,
  ga: GoogleAnalyticsIcon,
  github: GitHubIcon,
  google_docs: GoogleDocsIcon,
  laminar: LaminarIcon,
  linear: LinearIcon,
  mixpanel: MixpanelIcon,
  mongodb: MongodbIcon,
  mysql: MysqlIcon,
  postgres: PostgresIcon,
  supabase: SupabaseIcon,
  posthog: PostHogIcon,
  sentry: SentryIcon,
} as const;

function hasProviderIcon(
  provider: string
): provider is keyof typeof ProviderIcons {
  return provider in ProviderIcons;
}

export function getProviderIcon(
  provider: string
): ComponentType<ProviderIconProps> {
  if (hasProviderIcon(provider)) {
    return ProviderIcons[provider];
  }
  return UnknownProviderIcon;
}
